/* Independently composed TODOROKI examples. Scope checked 2026-11-02. */
lessons.push(...[{"subject": "商業簿記", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-20261102-01", "title": "将来減算一時差異の仕訳", "body": "会計上費用でも税務上は翌期以降の損金になる額は、将来の税負担を軽くする可能性があります。回収可能性を満たす範囲で繰延税金資産を認識します。例：損金不算入の賞与引当金240,000円、解消時税率30％、全額回収可能なら、借：繰延税金資産72,000／貸：法人税等調整額72,000。", "tag": "商業簿記｜税効果会計", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-20261102-02", "title": "将来加算一時差異の仕訳", "body": "会計上の資産額が税務上の資産額より大きく、将来解消時に課税所得が増える場合は、繰延税金負債を検討します。例：損益を通じた一時差異200,000円、税率30％なら借：法人税等調整額60,000／貸：繰延税金負債60,000。純資産に直接計上した評価差額の税効果は、その評価差額から控除します。", "tag": "商業簿記｜税効果会計", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-20261102-03", "title": "非支配株主への当期利益配分", "body": "子会社の当期利益には親会社以外の株主に帰属する部分も含まれます。連結修正後の子会社利益に非支配持分比率を掛けて配分します。例：修正後利益500万円、親会社80％所有なら非支配株主に帰属する当期純利益は100万円。連結利益全額を親会社の利益にしません。", "tag": "商業簿記｜連結会計", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-20261102-04", "title": "内部債権の貸倒引当金を消去する", "body": "連結内部の売掛金と買掛金を消去すると、その内部売掛金に対する貸倒引当金も不要になります。当期繰入分のみなら借：貸倒引当金／貸：貸倒引当金繰入で取り消します。例：内部売掛金400,000円、引当率2％なら取消額8,000円。外部債権分は残します。", "tag": "商業簿記｜連結会計", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-20261102-05", "title": "アップストリームの利益修正", "body": "子会社から親会社へ売った商品の未実現利益は、子会社側の利益を減らします。その修正は非支配株主への利益配分にも影響します。例：未実現利益100,000円、非支配比率20％なら、非支配株主帰属利益を20,000円減額。税効果を扱う場合は別途調整します。", "tag": "商業簿記｜連結会計", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-20261102-06", "title": "支配を維持した追加取得", "body": "子会社株式を追加取得しても支配が継続する場合は、非支配株主との資本取引として扱います。追加のれんを機械的に計上しません。例：非支配株主持分の減額300万円に対し支払350万円なら、差額50万円は資本剰余金の減額。ここでは税効果や取引費用を除きます。", "tag": "商業簿記｜連結会計", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "工事契約", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-07", "title": "進捗度と累計収益から当期収益へ", "body": "一定期間にわたり履行義務が充足され、原価比例法が適切な契約を仮定します。契約価格×累計進捗度で累計収益を求め、前期までの計上額を引きます。例：価格1,200万円、総原価1,000万円、累計原価600万円なら累計収益720万円。前期収益300万円なら当期420万円です。", "tag": "商業簿記｜工事契約", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "リース", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-08", "title": "借手の利息法と元本返済（2027年度）", "body": "2027年度の借手の基本処理では、使用権資産とリース負債を計上し、支払額を利息と負債返済に分けます。例：期首負債1,000,000円、利率3％、年末支払280,000円なら利息30,000円、元本250,000円、期末負債750,000円。使用権資産の償却は別に計算します。", "tag": "商業簿記｜リース", "years": [2027]}, {"subject": "会計学", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-20261102-09", "title": "永久差異に税効果を付けない", "body": "会計上の費用と税務上の損金の違いが将来も解消しない場合、一時差異とは区別します。例：将来も損金にならない費用80,000円について、税率30％を掛けた24,000円を繰延税金資産にしてはいけません。税率差異の原因として分析することと、資産を認識することは別です。", "tag": "会計学｜税効果会計", "years": [2026, 2027]}, {"subject": "会計学", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-20261102-10", "title": "回収可能性がある額まで認識する", "body": "将来減算一時差異があるだけでは全額の税資産を計上できません。将来の課税所得などに照らし、回収できる範囲を判断します。例：差異500,000円のうち損金算入による税負担軽減が見込める額300,000円、税率30％なら認識額90,000円。", "tag": "会計学｜税効果会計", "years": [2026, 2027]}, {"subject": "会計学", "topic": "期中財務諸表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=162", "sourceLabel": "企業会計基準第37号（範囲・定義）", "reviewed": "2026-11-02", "id": "exp-20261102-11", "title": "期中会計期間と累計期間", "body": "期中会計期間は年度より短く区分した期間、累計期間は期首から期中末までの期間です。4月開始年度なら7～9月の3か月と4～9月の6か月は異なります。企業会計基準第37号は2026年度から日商の出題対象です。2027年度で初めて対象になると考えないようにします。", "tag": "会計学｜期中財務諸表", "years": [2026, 2027]}, {"subject": "会計学", "topic": "期中財務諸表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=162", "sourceLabel": "企業会計基準第37号（範囲・定義）", "reviewed": "2026-11-02", "id": "exp-20261102-12", "title": "臨時計算書類と適用範囲", "body": "年度途中の計算書類でも、目的が異なれば同じ基準の対象とは限りません。期中財務諸表の基準は対象範囲を確認して使います。会社法上、分配可能額に反映するための臨時計算書類は、企業会計基準第37号の対象となる期中財務諸表に含まれないと整理されています。", "tag": "会計学｜期中財務諸表", "years": [2026, 2027]}, {"subject": "会計学", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-20261102-13", "title": "支配獲得後ののれんの償却", "body": "のれんは取得時に計上したまま永久に残すのではなく、効果の及ぶ期間にわたり20年以内で規則的に償却します。例：のれん600万円、合理的な償却期間10年、定額法、通年なら年額60万円。減損の検討はこの償却とは別に必要です。", "tag": "会計学｜連結会計", "years": [2026, 2027]}, {"subject": "会計学", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-20261102-14", "title": "支配獲得日の非支配株主持分", "body": "識別可能な子会社純資産を時価評価した額に、非支配持分比率を掛けます。例：時価評価後純資産2,000万円、親会社80％なら非支配株主持分400万円。ここでは税効果反映後の純資産額を与え、他の調整や潜在株式はないものとします。", "tag": "会計学｜連結会計", "years": [2026, 2027]}, {"subject": "会計学", "topic": "リース", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-15", "title": "年度別に借手の区分を整理する", "body": "2026年度は従来のリース取引の区分を前提に学習し、2027年度は新しい借手の処理を区別して学びます。新基準の借手は従来のファイナンスとオペレーティングという区分によって資産計上の有無を決めません。短期・少額等の取扱いは別途確認します。貸手側の区分と混同しないようにします。", "tag": "会計学｜リース", "years": [2026, 2027]}, {"subject": "会計学", "topic": "総論", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-16", "title": "公表日と試験の適用年度", "body": "新しい会計基準が公表されても直ちに当年度の試験へ適用されるわけではありません。出題区分表の年度と、4月1日時点の施行・公式の個別案内を確認します。2027年度の確定版は2026年7月公表ですが、適用開始は2027年4月1日です。早期適用を認める基準も、そのことだけで出題対象にはなりません。", "tag": "会計学｜総論", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：部門別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-17", "title": "連立方程式で補助部門を相互配賦", "body": "純粋の相互配賦法では相互サービスを含む総額を連立方程式で求めます。例：動力部門Pの直接費90,000円、修繕部門Rは60,000円。PはRの20％、RはPの10％を利用するとP＝90,000＋0.2R、R＝60,000＋0.1P。製造部門へは相互配賦分を除いた額を配賦します。", "tag": "工業簿記｜部門別計算", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：組別総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-18", "title": "組ごとに原価をまとめる", "body": "異なる種類を継続生産する場合、組別に直接費を集め、共通の加工費等を基準に沿って配賦します。例：共通加工費300,000円、機械時間A組200・B組100時間ならA組200,000円。A組の直接材料費90,000円、完成100個、仕掛品なしなら単価2,900円です。", "tag": "工業簿記｜組別総合原価計算", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：等級別総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-19", "title": "等価係数で換算量をそろえる", "body": "同種の製品で大きさなどが異なる場合、等価係数×数量で換算し共通原価を配分します。例：A100個・係数1、B50個・係数2なら換算量は各100。総原価200,000円を各100,000円に配分するので、実物1個当たり原価はA1,000円、B2,000円です。", "tag": "工業簿記｜等級別総合原価計算", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：連産品原価の計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-20", "title": "分離点の売価で連結原価を配分", "body": "分離点までは一体で発生した連結原価を、設問で指定する基準で各製品へ配分します。例：分離点の売価総額がA600,000円、B400,000円、連結原価500,000円ならA300,000円。追加加工の可否では、配分済み連結原価ではなく分離点後の増分を比較します。", "tag": "工業簿記｜連産品原価の計算", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：実際総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-21", "title": "先入先出法の当期加工換算量", "body": "先入先出法では期首仕掛品に前期投入済みの加工を当期換算量に含めません。例：期首100個・40％、完成500個、期末80個・50％なら当期加工換算量＝500＋80×50％−100×40％＝500個。材料の投入点と加工の進捗は区別します。", "tag": "工業簿記｜実際総合原価計算", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：個別原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-22", "title": "補修費を特定指図書へ負担させる", "body": "正常な仕損の補修費を当該指図書に直接負担させる条件では、その注文の原価へ加算します。例：本体原価150,000円、補修材料8,000円・労務費12,000円・配賦間接費5,000円なら完成原価175,000円。異常仕損や間接費処理を指定した場合は別です。", "tag": "工業簿記｜個別原価計算", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：費目別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-23", "title": "賃金支払額から当月消費額へ", "body": "当月に支払った額と当月に発生した賃金は一致するとは限りません。当月消費額＝当月支払額＋当月末未払額−前月末未払額です。例：支払500,000円、月初未払80,000円、月末未払100,000円なら520,000円。直接・間接の区分はさらに作業内容で行います。", "tag": "工業簿記｜費目別計算", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：工場会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-24", "title": "本社が工場の材料代を支払う", "body": "工場会計が独立し、本社が工場用材料を直接払いした場合、工場側は材料の増加と本社への内部勘定を記録します。例：工場側は借：材料100,000／貸：本社100,000。本社側は借：工場100,000／貸：普通預金100,000。合併時には内部勘定を相殺します。", "tag": "工業簿記｜工場会計", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：原価予測", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-25", "title": "高低点法で変動費率を推定する", "body": "操業度が最も高い点と低い点の差から変動費率を求めます。例：1,000時間で500,000円、600時間で380,000円なら変動費率300円／時間、固定費200,000円。費用が最大と最小の月ではなく、操業度で選ぶ点に注意します。", "tag": "原価計算｜原価予測", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：戦略的原価計算", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-26", "title": "活動基準で段取費を配賦する", "body": "活動基準原価計算では、活動別に集めた原価をその消費を表すドライバーで配賦します。例：段取費240,000円、全体12回なら1回20,000円。製品Aが3回利用した場合は60,000円。機械時間だけで一括配賦したときとの違いを考えます。", "tag": "原価計算｜戦略的原価計算", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：戦略的原価計算", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-27", "title": "目標利益から許容原価を求める", "body": "原価企画では市場を踏まえた目標売価から目標利益を引いて、達成すべき許容原価を考えます。例：売価5,000円、売上高利益率20％なら利益1,000円、許容原価4,000円。現在の見積原価4,500円なら低減目標は500円です。", "tag": "原価計算｜戦略的原価計算", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：事業部制", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-28", "title": "残余利益で資本コストを差し引く", "body": "残余利益は、事業利益から事業投資額に対する要求利益を引く指標です。例：利益1,500,000円、投資10,000,000円、要求利益率10％なら残余利益500,000円。投資額や利益の範囲をそろえ、率の指標であるROIと区別します。", "tag": "原価計算｜事業部制", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-29", "title": "内製外注で回避可能費だけを比較", "body": "外注にしても残る固定費は、選択肢間の差額になりません。例：1個の内製変動費400円、回避可能固定費80円、外注価格450円なら外注が30円有利。回避不能固定費や過去の設備支出を足して比較しないようにします。", "tag": "原価計算｜業務的意思決定", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-20261102-30", "title": "連産品の追加加工の判断", "body": "分離点までに発生した連結原価は、追加加工の可否では両案に共通です。追加加工による売上増加額と追加加工費を比較します。例：分離点売却額300,000円、追加加工後420,000円、追加費用90,000円なら増分利益30,000円。配分された原価をもう一度差し引きません。", "tag": "原価計算｜業務的意思決定", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：予算編成", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-31", "title": "売上予算から現金回収予算へ", "body": "掛売上の予算額と現金回収額は回収条件を通じて結び付けます。例：当月売上の60％を当月、40％を翌月回収し、前月売上800,000円・当月売上1,000,000円なら当月回収は920,000円。貸倒れや前受けなどがある場合は別に組み込みます。", "tag": "原価計算｜予算編成", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-20261102-32", "title": "多品種の販売構成を固定して分析", "body": "多品種では販売構成を仮定して加重平均の限界利益を使います。例：Aの単位限界利益600円、B400円、販売個数比1対1なら平均500円。固定費500,000円なら合計1,000個が損益分岐点です。構成が変わればこの分岐点も変わります。", "tag": "原価計算｜原価・営業量・利益関係分析", "years": [2026, 2027]}]);
qs.push(...[{"subject": "商業簿記", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-q-20261102-01", "q": "損金算入が翌期の賞与引当金360,000円。解消時税率30％、全額回収可能、期首の税効果残高0。他の差異なし。期末整理は？", "a": ["借：繰延税金資産108,000／貸：法人税等調整額108,000", "借：法人税等調整額108,000／貸：繰延税金負債108,000", "借：繰延税金資産360,000／貸：法人税等調整額360,000"], "correct": 0, "ex": "360,000×30％＝108,000円。将来の損金算入が税負担を軽くするため、資産を計上します。", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-q-20261102-02", "q": "損益を通じて生じた将来加算一時差異150,000円。期首残高0、解消時税率30％、税効果の例外なし。計上する負債は？", "a": ["45,000円", "150,000円", "繰延税金資産45,000円"], "correct": 0, "ex": "150,000×30％＝45,000円。将来の追加税負担に対応する繰延税金負債です。", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-q-20261102-03", "q": "期首から親会社が子会社株式75％を所有。子会社の連結修正後当期利益640万円。持分変動なし。非支配株主に帰属する当期純利益は？", "a": ["160万円", "480万円", "640万円"], "correct": 0, "ex": "640×（1−75％）＝160万円。親会社に帰属する部分は480万円です。", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-q-20261102-04", "q": "親会社の子会社向け売掛金600,000円と同額の買掛金を相殺消去する。内部債権への貸倒引当金は当期繰入の3％。税効果なし。引当金の取消額は？", "a": ["18,000円", "600,000円", "582,000円"], "correct": 0, "ex": "600,000×3％＝18,000円。借：貸倒引当金18,000／貸：貸倒引当金繰入18,000。", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-q-20261102-05", "q": "子会社から親会社への販売に係る期末未実現利益80,000円を消去する。非支配持分25％、税効果なし。他の修正なし。非支配株主帰属利益への影響は？", "a": ["20,000円減少", "60,000円減少", "影響なし"], "correct": 0, "ex": "80,000×25％＝20,000円減少。親会社が売手の場合と区別します。", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-q-20261102-06", "q": "支配継続の追加取得。非支配株主持分の減額240万円、追加取得対価290万円。他の調整なし。差額の連結処理は？", "a": ["資本剰余金50万円の減額", "のれん50万円の計上", "取得損失50万円"], "correct": 0, "ex": "290−240＝50万円。借：非支配株主持分240・資本剰余金50／貸：現金預金290（万円）。", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "工事契約", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-07", "q": "原価比例法が適切な工事。契約価格1,500万円、見積総原価1,200万円、累計原価720万円、前期までの収益450万円。契約変更なし。当期収益は？", "a": ["450万円", "900万円", "270万円"], "correct": 0, "ex": "進捗度720÷1,200＝60％。累計収益1,500×60％＝900万円、当期900−450＝450万円。", "years": [2026, 2027]}, {"subject": "商業簿記", "topic": "リース", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-08", "q": "2027年度・借手。期首リース負債900,000円、年利4％、年末支払260,000円。利息法、変更・追加支払なし。支払後の負債は？", "a": ["676,000円", "640,000円", "936,000円"], "correct": 0, "ex": "利息900,000×4％＝36,000円、元本260,000−36,000＝224,000円。900,000−224,000＝676,000円。", "years": [2027]}, {"subject": "会計学", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-q-20261102-09", "q": "将来も損金にならない費用100,000円だけがある。税率30％、他の差異なし。この費用に係る繰延税金資産は？", "a": ["0円", "30,000円", "100,000円"], "correct": 0, "ex": "将来の課税所得を減額する差異ではないので、一時差異に係る税効果は認識しません。", "years": [2026, 2027]}, {"subject": "会計学", "topic": "税効果会計", "sourceUrl": "https://www.fsa.go.jp/p_mof/singikai/kaikei/tosin/1a918b.htm", "sourceLabel": "税効果会計に係る会計基準 第二（認識・測定）", "reviewed": "2026-11-02", "id": "exp-q-20261102-10", "q": "将来減算一時差異800,000円のうち回収可能な税効果に対応する差異は500,000円と判定済み。税率30％。認識する繰延税金資産は？", "a": ["150,000円", "240,000円", "90,000円"], "correct": 0, "ex": "500,000×30％＝150,000円。回収不能部分300,000×30％＝90,000円は計上しません。", "years": [2026, 2027]}, {"subject": "会計学", "topic": "期中財務諸表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=162", "sourceLabel": "企業会計基準第37号（範囲・定義）", "reviewed": "2026-11-02", "id": "exp-q-20261102-11", "q": "4月1日開始、翌3月31日終了の年度。9月30日までの期首からの累計期間は？", "a": ["4月1日～9月30日", "7月1日～9月30日", "4月1日～翌3月31日"], "correct": 0, "ex": "期首から9月30日までの6か月です。直近3か月の期中会計期間と区別します。", "years": [2026, 2027]}, {"subject": "会計学", "topic": "期中財務諸表", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=162", "sourceLabel": "企業会計基準第37号（範囲・定義）", "reviewed": "2026-11-02", "id": "exp-q-20261102-12", "q": "会社法上の分配可能額の算定などを目的とする臨時計算書類と、企業会計基準第37号の関係は？", "a": ["同基準の対象となる期中財務諸表には含まれない", "年度途中なら全て同基準を強制適用する", "連結のみ同基準を強制適用する"], "correct": 0, "ex": "第37号BC22の範囲の整理によります。「年度途中」という時期だけで適用範囲を決めません。", "years": [2026, 2027]}, {"subject": "会計学", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-q-20261102-13", "q": "期首取得で生じたのれん480万円。効果の及ぶ合理的期間8年、定額法、減損なし。当期償却額は？", "a": ["60万円", "24万円", "償却しない"], "correct": 0, "ex": "480÷8＝60万円。日本基準での規則的償却の例です。", "years": [2026, 2027]}, {"subject": "会計学", "topic": "連結会計", "sourceUrl": "https://www.asb-j.jp/jp/wp-content/uploads/sites/4/ikan_20240701_34.pdf", "sourceLabel": "企業会計基準第22号（資本連結・内部取引消去）", "reviewed": "2026-11-02", "id": "exp-q-20261102-14", "q": "取得日の時価評価・税効果反映後の子会社純資産3,600万円。親会社70％取得。他の調整なし。取得日の非支配株主持分は？", "a": ["1,080万円", "2,520万円", "3,600万円"], "correct": 0, "ex": "3,600×30％＝1,080万円。取得対価に30％を掛けるのではありません。", "years": [2026, 2027]}, {"subject": "会計学", "topic": "リース", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-15", "q": "2027年度・新基準の借手側の基本的な理解として適切なのは？", "a": ["使用権資産・リース負債の認識を基本とし、短期・少額等を別途検討する", "従来のオペレーティング区分なら必ず簿外処理", "借手・貸手とも全て区分がなくなる"], "correct": 0, "ex": "借手側の新たな基本処理と例外を分けます。貸手側にはファイナンス・オペレーティングの区分があります。", "years": [2026, 2027]}, {"subject": "会計学", "topic": "総論", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-16", "q": "2027年度確定版が2026年7月に公表された。2026年度試験で使う出題区分表は？", "a": ["2022年度版を基本とし、2026年度の公式案内も確認する", "公表された日に2027年度版へ切り替わる", "受験者が好きな年度を選ぶ"], "correct": 0, "ex": "試験年度で区別します。第37号のように2026年度から対象とされる事項の公式案内にも注意します。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：部門別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-17", "q": "補助部門A＝80,000＋0.2B、B＝40,000＋0.1A（円）。純粋相互配賦法のA総額は？端数四捨五入。", "a": ["89,796円", "88,000円", "120,000円"], "correct": 0, "ex": "A＝80,000＋0.2（40,000＋0.1A）＝88,000＋0.02A。0.98A＝88,000、A≒89,796円。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：組別総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-18", "q": "A組材料費120,000円。共通加工費360,000円を機械時間A組300・B組150で配賦。A組完成180個、期首・期末仕掛品なし。A組完成品単価は？", "a": ["2,000円", "2,667円", "1,333円"], "correct": 0, "ex": "A組加工費360,000×300÷450＝240,000円。合計360,000÷180＝2,000円。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：等級別総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-19", "q": "A120個・等価係数1、B80個・等価係数1.5。総原価480,000円、仕掛品・仕損なし。Bの1個当たり原価は？", "a": ["3,000円", "2,000円", "2,400円"], "correct": 0, "ex": "換算量A120、B120、合計240。B配分240,000円÷80個＝3,000円。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：連産品原価の計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-20", "q": "分離点の売価総額X900,000円、Y600,000円。連結原価750,000円を分離点売価比率法で配分。X配分額は？", "a": ["450,000円", "375,000円", "300,000円"], "correct": 0, "ex": "750,000×900,000÷1,500,000＝450,000円。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：実際総合原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-21", "q": "期首仕掛品120個・加工進捗50％、完成800個、期末200個・加工進捗30％。仕損なし、先入先出法。当期加工費の完成品換算量は？", "a": ["800個", "860個", "920個"], "correct": 0, "ex": "800＋200×30％−120×50％＝800個。当期加工費を配分する分母です。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：個別原価計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-22", "q": "正常仕損の補修費を当該指図書へ賦課する。本体原価280,000円、補修材料12,000円・労務費18,000円・間接費10,000円。他の原価なし。完成原価は？", "a": ["320,000円", "280,000円", "300,000円"], "correct": 0, "ex": "280,000＋12,000＋18,000＋10,000＝320,000円。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：費目別計算", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-23", "q": "賃金支払額640,000円、月初未払賃金90,000円、月末未払賃金120,000円。他の調整なし。当月発生額は？", "a": ["670,000円", "610,000円", "850,000円"], "correct": 0, "ex": "640,000＋120,000−90,000＝670,000円。月初未払分は前月の発生額です。", "years": [2026, 2027]}, {"subject": "工業簿記", "topic": "工原：工場会計", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-24", "q": "独立工場会計で本社が工場用材料代180,000円を支払った。材料は工場で受入済み。工場側の仕訳は？", "a": ["借：材料180,000／貸：本社180,000", "借：本社180,000／貸：材料180,000", "借：材料180,000／貸：売上180,000"], "correct": 0, "ex": "支払った主体は本社なので、工場の普通預金を減らさず本社勘定を使います。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：原価予測", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-25", "q": "高操業1,200時間・総費用660,000円、低操業800時間・総費用500,000円。直線費用を仮定。1,000時間の予測費用は？", "a": ["580,000円", "550,000円", "600,000円"], "correct": 0, "ex": "変動費率160,000÷400＝400円／時間。固定費660,000−400×1,200＝180,000円。1,000時間なら580,000円。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：戦略的原価計算", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-26", "q": "段取活動原価480,000円、全製品の段取20回。製品Xは6回利用。段取回数で配賦する場合、X配賦額は？", "a": ["144,000円", "80,000円", "288,000円"], "correct": 0, "ex": "480,000÷20＝24,000円／回。24,000×6＝144,000円。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：戦略的原価計算", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-27", "q": "目標売価8,000円、目標利益は売上高の25％。見積原価6,700円。必要な原価低減額は？", "a": ["700円", "2,000円", "1,300円"], "correct": 0, "ex": "目標利益2,000円、許容原価6,000円。6,700−6,000＝700円を低減します。原価に対する利益率と混同しません。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：事業部制", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-28", "q": "事業利益240万円、平均投資額1,500万円、要求利益率12％。残余利益は？", "a": ["60万円", "16％", "180万円"], "correct": 0, "ex": "要求利益1,500×12％＝180万円。240−180＝60万円。ROIは240÷1,500＝16％です。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-29", "q": "1,000個を内製する変動費500,000円、外注で全額回避できる固定費120,000円、回避不能固定費200,000円。外注総額650,000円、他用途なし。どちらが有利？", "a": ["内製が30,000円有利", "外注が170,000円有利", "同じ"], "correct": 0, "ex": "内製の関連原価500,000＋120,000＝620,000円。外注650,000円より30,000円小さい。回避不能200,000円は両案共通です。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：業務的意思決定", "sourceUrl": "https://www.asb-j.jp/jp/accounting_standards_system/details.html?topics_id=156", "sourceLabel": "企業会計審議会：原価計算基準（計算例は独自作成）", "reviewed": "2026-11-02", "id": "exp-q-20261102-30", "q": "分離点売却額540,000円、追加加工後売却額720,000円、追加加工費210,000円。他の影響なし。追加加工による利益変化は？", "a": ["30,000円減少", "180,000円増加", "510,000円増加"], "correct": 0, "ex": "売上増加720,000−540,000＝180,000円、追加費用210,000円。差額は−30,000円なので分離点売却が有利です。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：予算編成", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-31", "q": "売上の70％を当月、30％を翌月回収。前月売上900,000円、当月売上1,200,000円、貸倒れ・他の回収なし。当月回収予算は？", "a": ["1,110,000円", "1,200,000円", "1,290,000円"], "correct": 0, "ex": "1,200,000×70％＋900,000×30％＝840,000＋270,000＝1,110,000円。", "years": [2026, 2027]}, {"subject": "原価計算", "topic": "工原：原価・営業量・利益関係分析", "sourceUrl": "https://www.kentei.ne.jp/bookkeeping/35697-2", "sourceLabel": "日本商工会議所：2026・2027年度出題区分表", "reviewed": "2026-11-02", "id": "exp-q-20261102-32", "q": "A単位限界利益900円、B600円。販売個数比A：B＝2：1を維持する。固定費720,000円。他の条件一定。損益分岐点の合計販売数量は？", "a": ["900個（A600・B300）", "800個（A約533・B約267）", "1,200個（A800・B400）"], "correct": 0, "ex": "3個1組の限界利益は900×2＋600＝2,400円。720,000÷2,400＝300組、合計900個です。", "years": [2026, 2027]}]);
